import express from 'express';
import cors from 'cors';
import { TelemetrySimulator } from './simulator.js';

const app = express();
app.use(cors());

// Initialize and spin up the shared simulator engine instance
const simulator = new TelemetrySimulator();
simulator.start();

// Dashboard endpoint — cleanly pulls cached context generated by the timer
app.get('/api/dashboard', (req, res) => {
  try {
    const data = simulator.getSnapshot();
    res.json(data);
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : 'Unknown Server Error';
    res.status(500).json({ error: errorMsg });
  }
});

export function startServer(port = 3000) {
  const server = app.listen(port, () => {
    console.log(`[Backend Server] Running on http://127.0.0.1:${port}`);
  });
  return server;
}

// Self-start hook for individual runtime (npm run backend)
if (require.main === module) {
  startServer();
}
